    /// Binds the typed `_event.data` view an inject seam carried (§scxml-5.10).
    public func populateEventMetadata(_ metadata: EventMetadata) {
        pendingPayloadTag = .none
        switch metadata.typedPayload {
        case let payload as StaticHostModelDoneInvokeGenPayload:
            pendingPayloadTag = .doneInvokeGen
            pendingDoneInvokeGenPayload = payload
        case let payload as StaticHostModelHostModelGenerateRequestPayload:
            pendingPayloadTag = .hostModelGenerateRequest
            pendingHostModelGenerateRequestPayload = payload
        default:
            break
        }
    }


    /// Reads the typed `_event.data` view out of the data every other producer
    /// carries, and refuses what the schema does not admit (§scxml-3.13).
    public func liftTypedPayload(event: StaticHostModelEvent, metadata: EventMetadata) throws {
        // A typed carrier already bound the view, so the producer was the inject
        // seam and there is nothing to read out of `data`.
        if pendingPayloadTag != .none {
            return
        }
        switch event {
        case .doneInvokeGen:
            let fields = try PayloadFields.decode(metadata.data)
            let sceField0: String = try fields.text("error", bound: 24)
            let sceField1: String = try fields.text("text", bound: 4096)
            let sceField2: Bool = try fields.truth("constrained")
            let sceField3: String = try fields.text("model", bound: 128)
            let sceField4: UInt32 = try fields.unsigned("prompt_tokens")
            let sceField5: UInt32 = try fields.unsigned("answer_tokens")
            let sceField6: String = try fields.text("finish", bound: 16)
            let payload = StaticHostModelDoneInvokeGenPayload(error: sceField0, text: sceField1, constrained: sceField2, model: sceField3, prompt_tokens: sceField4, answer_tokens: sceField5, finish: sceField6)
            pendingDoneInvokeGenPayload = payload
            pendingPayloadTag = .doneInvokeGen
        case .hostModelGenerateRequest:
            let fields = try PayloadFields.decode(metadata.data)
            let sceField0: String = try fields.text("prompt", bound: 8192)
            let sceField1: String = try fields.text("answer_schema", bound: 128)
            let sceField2: UInt32 = try fields.unsigned("max_tokens")
            let sceField3: UInt16 = try fields.unsigned("temperature_milli")
            let payload = StaticHostModelHostModelGenerateRequestPayload(prompt: sceField0, answer_schema: sceField1, max_tokens: sceField2, temperature_milli: sceField3)
            pendingHostModelGenerateRequestPayload = payload
            pendingPayloadTag = .hostModelGenerateRequest
        default:
            break
        }
    }


