    /// W3C SCXML 6.4: the `<invoke>`s a state's entry deferred to the end of the
    /// macrostep. A state exited before then drops its own.
    private var pendingInvokes: [PendingInvoke<StaticHostModelState>] = []

    /// Starts the sessions the macrostep's entries deferred (W3C SCXML 6.4), now that
    /// the macrostep is over.
    public func executePendingInvokes(engine: Engine<StaticHostModelPolicy>) {
        SceRuntime.executePendingInvokes(&pendingInvokes) { pending in
            if pending.documentID.utf8.elementsEqual("gen".utf8) {
                sceStartHostInvokeGen(engine: engine)
                return
            }
        }
    }

    /// Starts `<invoke type="sce-host-model-generate" id="gen">`
    /// (W3C SCXML 6.4.1): the invoker the host registered for the type is handed the
    /// request, under the id the DOCUMENT wrote, which is the name `done.invoke.<id>`
    /// carries. A type the host declared and never registered an invoker for is the same
    /// fact as an unsupported one, so the same event, and not a silence that reads as
    /// started.
    private func sceStartHostInvokeGen(engine: Engine<StaticHostModelPolicy>) {
        // W3C SCXML 6.4.1: what the request says is evaluated now, when the invocation
        // starts. The text the host reads is the one each value spells; the JSON is the
        // typed pairs, written once, so a host that forwards the request forwards the
        // engine's serialisation. A value that cannot be evaluated starts nothing.
        var hostParams: [String: [String]] = [:]
        var hostParts: [PayloadPair] = []
        do {
            let sceValue: WireValue = .text(self.vPrompt)
            appendFormParam(&hostParams, "prompt", sceValue)
            hostParts.append(PayloadPair("prompt", sceValue))
        }
        do {
            let sceValue: WireValue = .integer(Int64(self.vMaxTokens))
            appendFormParam(&hostParams, "max_tokens", sceValue)
            hostParts.append(PayloadPair("max_tokens", sceValue))
        }
        do {
            let sceValue: WireValue = .integer(Int64(self.vTemperatureMilli))
            appendFormParam(&hostParams, "temperature_milli", sceValue)
            hostParts.append(PayloadPair("temperature_milli", sceValue))
        }
        do {
            let sceValue: WireValue = .integer(Int64(1000))
            appendFormParam(&hostParams, "_sce_deadline_ms", sceValue)
            hostParts.append(PayloadPair("_sce_deadline_ms", sceValue))
        }
        appendFormParam(&hostParams, "answer_schema", .text("urn:sce:schema:lift_answer:2"))
        hostParts.append(PayloadPair("answer_schema", .text("urn:sce:schema:lift_answer:2")))
        let request = HostInvokeRequest(
            processorType: "sce-host-model-generate",
            invokeID: "gen",
            params: hostParams,
            eventData: hostParts.isEmpty ? "" : payloadJSON(hostParts),
            sessionID: sessionID
        )
        if !engine.performHostInvoke(request) {
            engine.raise(EventWithMetadata.platformError(StaticHostModelEvent.errorExecution, message: "<invoke> names an invoker the host declared but never registered"))
        }
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: StaticHostModelState, engine: Engine<StaticHostModelPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .generating:
            // W3C SCXML 6.4.1: an <invoke> a host runs is deferred like any other, so a
            // state that exits before the macrostep ends never starts it. The id it is
            // started under is the document's: `done.invoke.<id>` is the name the author
            // wrote a transition for.
            deferInvoke(&pendingInvokes, PendingInvoke(
                invokeID: "gen",
                state: .generating,
                documentID: "gen"
            ))
        default:
            break  // No entry actions
        }
    }

    /// Runs a `<history>`'s default transition content (W3C SCXML 3.10.2), after
    /// its parent's onentry (and after the parent's own `<initial>` content) when
    /// the history was taken with nothing recorded. The engine asks for it by the
    /// entry set's defaultHistoryContent answer; a history that restored what it
    /// recorded runs nothing.
    public func executeHistoryDefaultContent(_ history: HistoryID, engine: Engine<StaticHostModelPolicy>) {
        // W3C SCXML 3.10.2: no <history> in this document has default content.
    }

    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: StaticHostModelState, engine: Engine<StaticHostModelPolicy>, configurationBeforeExit: [StaticHostModelState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .generating:
            cancelInvokesForState(&pendingInvokes, .generating)
            engine.cancelHostInvoke(processorType: "sce-host-model-generate", invokeID: "gen")
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: StaticHostModelState,
        event: StaticHostModelEvent,
        engine: Engine<StaticHostModelPolicy>
    ) -> EnabledTransition<StaticHostModelState>? {
        switch state {
        case .generating:
            if event == .doneInvokeGen {
                // W3C SCXML 5.9: cond="_event.data.error === ''" lowered to Swift at build time
                if (self.pendingPayloadTag == .doneInvokeGen && (self.pendingDoneInvokeGenPayload.error.utf8.elementsEqual("".utf8))) {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.idle)],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeGen {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.idle)],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .errorInvokeGen {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.idle)],
                        transitionIndex: 2,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.idle)],
                        transitionIndex: 3,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .modelLeave {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.idle)],
                        transitionIndex: 4,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        case .idle:
            if event == .hostModelGenerateRequest {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.generating)],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

