/// `sce:result`: the record the host completes `<invoke id="gen">`
/// with (SCE Accepted Subset §2.12).
public struct StaticHostModelGenResult: Equatable, Sendable {
    public var error: String
    public var text: String
    public var constrained: Bool
    public var model: String
    public var prompt_tokens: UInt32
    public var answer_tokens: UInt32
    public var finish: String

    public init(error: String, text: String, constrained: Bool, model: String, prompt_tokens: UInt32, answer_tokens: UInt32, finish: String) {
        self.error = error
        self.text = text
        self.constrained = constrained
        self.model = model
        self.prompt_tokens = prompt_tokens
        self.answer_tokens = answer_tokens
        self.finish = finish
    }

    /// The JSON `done.invoke.gen` carries this record as, in the schema's order.
    public var wire: String {
        payloadJSON(.text("error", error), .text("text", text), .truth("constrained", constrained), .text("model", model), .integer("prompt_tokens", prompt_tokens), .integer("answer_tokens", answer_tokens), .text("finish", finish))
