/// The host side of this document's typed `<invoke type="sce-host-model-generate">`s (SCE
/// Accepted Subset §2.12). Register it with `registerStaticHostModelSceHostModelGenerateInvoker`.
public protocol StaticHostModelSceHostModelGenerateInvoker: AnyObject {
    /// §scxml-6.4: begin `<invoke id="gen">`. `token` names this start; a
    /// host that finishes later hands it back to `completeStaticHostModelGen`
    /// (or `completeHostInvoke`). A non-nil answer completes the invocation now.
    func startGen(_ request: StaticHostModelGenRequest, token: UInt64) -> StaticHostModelGenResult?

    /// §scxml-6.4: `<invoke id="gen">`'s state exited while the start `token`
    /// names was still running. Stop it.
    func cancelGen(token: UInt64)

}

/// Registers `invoker` as the handler for `type="sce-host-model-generate"`.
public func registerStaticHostModelSceHostModelGenerateInvoker(on engine: Engine<StaticHostModelPolicy>, invoker: StaticHostModelSceHostModelGenerateInvoker) throws(HostRegistrationError) {
    try engine.registerInvoker("sce-host-model-generate") { event in
        switch event {
        case .start(let start):
            if start.invokeID.utf8.elementsEqual("gen".utf8) {
                let typed = StaticHostModelGenRequest(prompt: start.requestString("prompt"), answer_schema: start.requestString("answer_schema"), max_tokens: start.requestInteger("max_tokens", as: UInt32.self), temperature_milli: start.requestInteger("temperature_milli", as: UInt16.self))
                if let result = invoker.startGen(typed, token: start.token) {
                    return .done(result.wire)
                }
                return nil
            }
            return nil
        case .cancel(let cancel):
            if cancel.invokeID.utf8.elementsEqual("gen".utf8) {
                invoker.cancelGen(token: cancel.token)
                return nil
            }
            return nil
        }
    }
}

/// Completes `<invoke id="gen">`'s start `token` with its record:
/// `completeHostInvoke` with the record's JSON, so a stale or unknown token is
/// refused the same way (false).
@discardableResult
public func completeStaticHostModelGen(on engine: Engine<StaticHostModelPolicy>, token: UInt64, result: StaticHostModelGenResult) -> Bool {
    engine.completeHostInvoke(processorType: "sce-host-model-generate", invokeID: "gen", token: token, doneData: result.wire)
}


